def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    woman_patches = image_patch.find("woman")
    tshirt_patches = image_patch.find("t-shirt")

    if not woman_patches or not tshirt_patches:
        return image_patch

    woman_tshirt_pairs = []
    for woman in woman_patches:
        for tshirt in tshirt_patches:
            if woman.overlaps_with(tshirt.left, tshirt.lower, tshirt.right, tshirt.upper):
