    baby_patches = image_patch.find("baby")
    elephant_patches = image_patch.find("elephant")

    if not baby_patches or not elephant_patches:
        return image_patch

    # Find the baby closest to the center of the elephant
    closest_baby = None
    min_distance = float('inf')

    for baby in baby_patches:
        for elephant in elephant_patches:
